//! Cross-language byte-exact verification of Rust `multi_gkr` and `multi_pcs` (mixed-size layer injection)
//! against golden vectors generated by Python `prover/fpn_prover/backend/{multi_gkr,multi_pcs}.py`.

use fpn_core::field::{eq_pt, Fp, Fp3};
use fpn_core::multi_gkr::{verify_multi_gkr, MultiGkrLayout};
use fpn_core::multi_pcs::{verify_multi_open, MultiPcsLayout};
use fpn_core::transcript::Fpn2Transcript;

fn unhex(s: &str) -> Vec<u8> {
    assert!(s.len().is_multiple_of(2));
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

fn unhex32(s: &str) -> [u8; 32] {
    unhex(s).try_into().unwrap()
}

/// Minimal zero-dependency JSON parser for the flat vector file (numbers, strings, arrays, objects).
#[derive(Clone, Debug)]
enum JVal {
    Num(u64),
    Str(String),
    Arr(Vec<JVal>),
    Obj(Vec<(String, JVal)>),
}

impl JVal {
    fn as_u64(&self) -> u64 {
        match self {
            JVal::Num(n) => *n,
            _ => panic!("expected num"),
        }
    }
    fn as_str(&self) -> &str {
        match self {
            JVal::Str(s) => s,
            _ => panic!("expected str"),
        }
    }
    fn as_arr(&self) -> &[JVal] {
        match self {
            JVal::Arr(v) => v,
            _ => panic!("expected arr"),
        }
    }
    fn get(&self, key: &str) -> &JVal {
        match self {
            JVal::Obj(m) => &m.iter().find(|(k, _)| k == key).expect(key).1,
            _ => panic!("expected obj"),
        }
    }
    fn as_fp3(&self) -> Fp3 {
        let a = self.as_arr();
        Fp3([
            Fp::new(a[0].as_u64()),
            Fp::new(a[1].as_u64()),
            Fp::new(a[2].as_u64()),
        ])
    }
}

fn parse_json(src: &str) -> JVal {
    let b = src.as_bytes();
    let mut i = 0usize;
    fn skip(b: &[u8], i: &mut usize) {
        while *i < b.len() && b[*i].is_ascii_whitespace() {
            *i += 1;
        }
    }
    fn parse_str(b: &[u8], i: &mut usize) -> String {
        assert_eq!(b[*i], b'"');
        *i += 1;
        let start = *i;
        while b[*i] != b'"' {
            *i += 1;
        }
        let s = std::str::from_utf8(&b[start..*i]).unwrap().to_string();
        *i += 1;
        s
    }
    fn parse_val(b: &[u8], i: &mut usize) -> JVal {
        skip(b, i);
        match b[*i] {
            b'"' => JVal::Str(parse_str(b, i)),
            b'[' => {
                *i += 1;
                let mut v = Vec::new();
                loop {
                    skip(b, i);
                    if b[*i] == b']' {
                        *i += 1;
                        return JVal::Arr(v);
                    }
                    v.push(parse_val(b, i));
                    skip(b, i);
                    if b[*i] == b',' {
                        *i += 1;
                    }
                }
            }
            b'{' => {
                *i += 1;
                let mut m = Vec::new();
                loop {
                    skip(b, i);
                    if b[*i] == b'}' {
                        *i += 1;
                        return JVal::Obj(m);
                    }
                    let k = parse_str(b, i);
                    skip(b, i);
                    assert_eq!(b[*i], b':');
                    *i += 1;
                    let val = parse_val(b, i);
                    m.push((k, val));
                    skip(b, i);
                    if b[*i] == b',' {
                        *i += 1;
                    }
                }
            }
            _ => {
                let start = *i;
                while *i < b.len() && b[*i].is_ascii_digit() {
                    *i += 1;
                }
                let n: u64 = std::str::from_utf8(&b[start..*i]).unwrap().parse().unwrap();
                JVal::Num(n)
            }
        }
    }
    parse_val(b, &mut i)
}

#[test]
fn cross_language_multi_gkr_and_multi_pcs_vectors() {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../specs/vectors/fpn2_multi_pcs_gkr.json"
    );
    let root = parse_json(&std::fs::read_to_string(path).expect("missing vector json"));

    // 1. Multi-GKR vectors
    for v in root.get("multi_gkr").as_arr() {
        let name = v.get("name").as_str();
        let lay = MultiGkrLayout::new(v.get("s").as_u64() as usize, v.get("m_mask").as_u64() as usize)
            .unwrap();
        let pf = unhex(v.get("proof_hex").as_str());
        let mut tr = Fpn2Transcript::new(v.get("label").as_str().as_bytes());
        let exp = v.get("expected").as_str();
        match verify_multi_gkr(&lay, &pf, &mut tr) {
            Ok(claims) => {
                assert_eq!(exp, "VERIFIED", "{name}: expected {exp}, got VERIFIED");
                assert_eq!(claims.num_eval, v.get("num_eval").as_fp3(), "{name}: num_eval");
                assert_eq!(claims.den_eval, v.get("den_eval").as_fp3(), "{name}: den_eval");
            }
            Err(code) => {
                assert_eq!(code.as_str(), exp, "{name}: wrong reject code");
            }
        }
    }

    // 2. Multi-PCS mixed-size layer-injection vectors
    for v in root.get("multi_pcs").as_arr() {
        let name = v.get("name").as_str();
        let n = v.get("n").as_u64() as usize;
        let queries = v.get("queries").as_u64() as usize;
        let gns: Vec<usize> = v
            .get("group_ns")
            .as_arr()
            .iter()
            .map(|x| x.as_u64() as usize)
            .collect();
        let lay = MultiPcsLayout::new(n, queries, gns).unwrap();
        let roots: Vec<[u8; 32]> = v
            .get("roots_hex")
            .as_arr()
            .iter()
            .map(|x| unhex32(x.as_str()))
            .collect();
        let claims: Vec<Fp3> = v.get("claims").as_arr().iter().map(|x| x.as_fp3()).collect();
        let pts: Vec<Vec<Fp3>> = v
            .get("pts")
            .as_arr()
            .iter()
            .map(|p| p.as_arr().iter().map(|x| x.as_fp3()).collect())
            .collect();
        let pf = unhex(v.get("proof_hex").as_str());
        let mut tr = Fpn2Transcript::new(v.get("label").as_str().as_bytes());
        let exp = v.get("expected").as_str();

        let res = verify_multi_open(
            &lay,
            &roots,
            &claims,
            |g, r_ip_g| eq_pt(&pts[g], r_ip_g),
            &pf,
            &mut tr,
        );
        match res {
            Ok(_) => assert_eq!(exp, "VERIFIED", "{name}: expected {exp}, got VERIFIED"),
            Err(code) => assert_eq!(code.as_str(), exp, "{name}: wrong reject code"),
        }
    }
}
